// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Why a media key was refused (mirrors `matrix_rtc_core::KeyRejection`).
 *
 * Typed rather than a message so a host can act on it: `NotCrossSigned` is a
 * "verify this device" prompt, not just something to log.
 */

public enum FfiKeyRejection {
    
    /**
     * Sent in cleartext, so the sender cannot be authenticated (MSC4143).
     */
    case cleartext
    /**
     * The sending device is not cross-signed (MSC4153).
     */
    case notCrossSigned
    /**
     * The message named a different room than this session's.
     */
    case roomMismatch(claimed: String
    )
    /**
     * The sender does not match the one on the member event it claims.
     */
    case senderMismatch(expected: String, actual: String
    )
    /**
     * The member event names no sending device, so the required match cannot be
     * performed at all.
     */
    case unverifiableDevice
    /**
     * The sending device is not the one that sent the member event.
     */
    case deviceMismatch(expected: String, actual: String?
    )
}


#if compiler(>=6)
extension FfiKeyRejection: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiKeyRejection: FfiConverterRustBuffer {
    typealias SwiftType = FfiKeyRejection

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiKeyRejection {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .cleartext
        
        case 2: return .notCrossSigned
        
        case 3: return .roomMismatch(claimed: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .senderMismatch(expected: try FfiConverterString.read(from: &buf), actual: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .unverifiableDevice
        
        case 6: return .deviceMismatch(expected: try FfiConverterString.read(from: &buf), actual: try FfiConverterOptionString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiKeyRejection, into buf: inout [UInt8]) {
        switch value {
        
        
        case .cleartext:
            writeInt(&buf, Int32(1))
        
        
        case .notCrossSigned:
            writeInt(&buf, Int32(2))
        
        
        case let .roomMismatch(claimed):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(claimed, into: &buf)
            
        
        case let .senderMismatch(expected,actual):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(expected, into: &buf)
            FfiConverterString.write(actual, into: &buf)
            
        
        case .unverifiableDevice:
            writeInt(&buf, Int32(5))
        
        
        case let .deviceMismatch(expected,actual):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(expected, into: &buf)
            FfiConverterOptionString.write(actual, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiKeyRejection_lift(_ buf: RustBuffer) throws -> FfiKeyRejection {
    return try FfiConverterTypeFfiKeyRejection.lift(buf)
